import{_ as a,a as i}from"./chunks/14d461bc9c380468c698.4JpU8QKL.js";import{_ as l,C as o,o as r,c as s,j as e,a as n,E as c,a6 as h}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"8个步骤，让你彻底不再他人的看法","description":"","frontmatter":{"title":"8个步骤，让你彻底不再他人的看法","originalTitle":"8 Steps To Just Stop Giving A F*ck","date":"2024-09-14","originalUrl":"https://thedankoe.com/letters/8-steps-to-just-stop-giving-a-fck/","minutes":22,"sourceHash":"ac23b47e100dbd3f22ebfd4d50ddf5c6fd3529976517c741ab4ee7430f9209de","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/8-steps-to-just-stop-giving-a-fck/"}]]},"headers":[],"relativePath":"letters/8-steps-to-just-stop-giving-a-fck.md","filePath":"letters/8-steps-to-just-stop-giving-a-fck.md"}'),d={name:"letters/8-steps-to-just-stop-giving-a-fck.md"};function m(u,p,_,f,g,k){const t=o("ArticleMeta");return r(),s("div",null,[p[0]||(p[0]=e("h1",{id:"_8个步骤-让你彻底不再他人的看法",tabindex:"-1"},[n("8个步骤，让你彻底不再他人的看法 "),e("a",{class:"header-anchor",href:"#_8个步骤-让你彻底不再他人的看法","aria-label":'Permalink to "8个步骤，让你彻底不再他人的看法"'},"​")],-1)),c(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/63VycRr2AS8?si=RuNbfwtpMBSn4eal" target="_blank" rel="noreferrer">观看原文视频</a></p><p>如果你想不再在乎别人的想法……</p><p>如果你想带着自信和优雅穿行于这个世界……</p><p>如果你想建立事业、去追那个女孩、精通你的技艺，或者从生活中得到你想要的东西……</p><p>这里有8个步骤，让你彻底不再他妈的在乎那么多。</p><p>我们将会讨论：</p><ul><li>自信的三大支柱，让你能快速地不再在乎……</li><li>你一开始为什么这么在乎（有了这份觉察，你才能停下来）。</li><li>如何重新编程你的大脑，成为你本应成为的那个人。</li><li>为什么你可能正走在一条注定100%失败的人生道路上，以及如何逃脱。</li><li>如何培养属于你自己的内在指南针，找到你在生活中真正想要的东西。</li><li>发现你的兴趣、把提升变成执念的“热情流程”。</li><li>一个能加速改变你人生的工具。</li><li>现实的本质，以及它如何帮助你变得更有智慧（这样你就不会再为一些小麻烦而焦虑）。</li></ul><p>我不想让这篇文章又变成网上随处可见的那种浮于表面的步骤式建议贴。我想让你彻底解决这个问题。而这需要我们深入进去。</p><hr><p><strong>一个小小的提醒：</strong></p><p>我们将于9月20日（还有6天）开始逐步开放Kortex的使用权限。</p><p>你必须在Kortex的等候名单上才能获得访问权限。</p><p>泰林·西蒙兹（Taylin Simmonds）说：“这就像Notion、Obsidian和Google Docs生了个孩子。”</p><p>所以，如果你想要一个地方来：</p><ul><li>捕捉你所有的想法（不用再靠一份乱七八糟的笔记把它们全弄丢）</li><li>存储你从Kindle、网页、PDF、推文以及任何与Readwise集成的内容中划出的高光。</li><li>拥有一个互联互通的第二大脑，能孕育出清晰独到的写作。</li><li>撰写落地页、社媒帖子、视频脚本，或者你任何创意项目的内容。</li></ul><p>并且，还能获得一门免费的第二大脑课程和社区论坛的使用权……</p><p>点击这里加入<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex等候名单</a>。接下来几周内你会收到一封邮件来注册（没错，还有免费版本）。</p><hr><h2 id="_1-自信的三大支柱" tabindex="-1">1）自信的三大支柱 <a class="header-anchor" href="#_1-自信的三大支柱" aria-label="Permalink to &quot;1）自信的三大支柱&quot;">​</a></h2><p>不再他妈的在乎的第一步，是理解自信这件事的全局，而不只是那些肤浅的建议。</p><p>如果自信像看一个关于自信的YouTube视频那么简单，我们早就活在乌托邦里了。</p><p>这背后有更深层的东西在运作，我希望能在这篇文章里让你意识到这一点。</p><p>缺乏自信是困扰大多数人潜力的头号问题。他们太在乎别人怎么想了。</p><p>假设你想创业，各种念头开始涌进来：</p><p>我父母会怎么想？</p><p>我朋友会怎么想？</p><p>我配偶会怎么想？</p><p>这够不够替代我的收入？</p><p>要花多长时间？</p><p>更别提当你真正开始建立这份事业时冒出来的那些念头了。</p><p>人们失败的原因，是他们扛不起实现目标所需要承受的那份情绪重量。</p><p>每一个关于更好生活的念头出现时，都有100个念头把你打回去。</p><p>而这仅仅是关于创业的念头。</p><p>那我们每天其他的6万到8万个念头呢？</p><p>我们要操心的事情实在太多了。</p><p>我试着交新朋友时会不会显得很怪？</p><p>如果我控制不住债务，最后会落到什么地步？</p><p>我今天早上给狗喂食了吗？想象一下，要是别人知道了，会觉得我是多么糟糕的宠物主人。</p><p>培养自信绝非易事。</p><p>更多的信息、更多的责任、更多关于未来的选项，会把自信变成成功，把焦虑变成失败。</p><p>这就是我们所生活的现代环境。</p><p>我们该如何开始培养那种通向自信的自我信任？</p><p>当大多数人在思考如何变得更自信时，都会被提醒那句简单化的建议：</p><p>“自信=能力。”</p><p>这话没错，但大多数人会把“能力”理解为在某项具体技能上变得更强。</p><p>于是他们不断地学、学、学，却从不行动，从不自我反思，也从没在任何情境中真正把自信培养成一种技能。这是最常见的结果。</p><p>在这句简单陈述背后，藏着很少有人能看透的深意。</p><p>我们必须努力去理解这句话，因为显然，“自信=能力”作为一句泛泛的建议，并没有解决世界上最大的问题之一，反而让它变得更糟。</p><p><strong>支柱1）视角</strong></p><p>当你进入一个让你感觉不自信的情境时，焦虑会瞬间飙升。</p><p>这会让你的大脑关闭一切，只剩下你的念头。</p><p>它们不断繁殖。</p><p>你完全从那个情境中退缩出来，成为你过去的奴隶——你以前经历过的那些经验。你还是原来那个人。</p><p>你必须打破这种状态，有意识地努力重新编程你对情境的习惯性反应方式。</p><p>要做到这一点：</p><ul><li>当你进入某个情境、焦虑被激发时，停下来</li><li>拉远视角，把这个情境看清楚——它其实只是一个普通的情境</li><li>把意识转移到情境中和你在一起的那个人身上</li></ul><p>“转移意识”就是采用另一个人的视角。</p><p>大多数人也只是过着和我们一样的人生经历的普通人。</p><p>亿万富翁也是有着同样问题的人。</p><p>健身模特也是有着同样问题的人。</p><p>任何你在心里把他们放到你之上的人，都有着同样的问题。</p><p>唯一会让他们对你产生负面反应的一件事，就是把他们当作不是人来对待。</p><p>别把他们放在你之上。</p><p>记住，这是你正在养成的一个习惯。</p><p>这需要反复练习。</p><p>如果你无法对一个情境获得视角，你就无法进阶到其他支柱。</p><p><strong>支柱2）感知</strong></p><p>你如何感知情境，决定了你如何行动。</p><p>这需要你在情境发生之前就转入开放心态，并在情境中保持这种状态。</p><p>如果你在刷社交媒体时，没有把一个企业主的推文感知为一个可以主动联系的机会，你就不会主动联系。</p><p>如果你把它看作一个机会，但因为对那个人的感知有误，你可能仍然会把私信搞砸，或者干脆一条也不发。</p><p>交新朋友或进行困难的对话也是同样的道理。</p><p>感知是双向的。</p><p>你基于对方展现自己的方式，以某种方式感知他们。</p><p>他们也基于你展现自己的方式来感知你。</p><p>如果你没有“表现出那个样子”，或者没有以一种能让对方产生正面解读的方式呈现自己，事情就不会顺利进行。而你在潜意识里会知道这一点。你不会去主动参与这些情境，因为你的外貌和行为方式已经把自己设定为失败。</p><p>我算是内向到不能再内向的人了，但人们常说我穿衣、走路、说话的样子看起来很自信。</p><p>练习。</p><p><strong>支柱3）练习</strong></p><p>你在某件事上有多擅长，决定了你能否更好地感知情境。</p><p>把技能获取想象成一种在“人生游戏”中提升等级的方式。</p><p>在一个电子游戏里，有“技能树”。</p><p>在玩游戏的过程中，你会选择技能，帮助你以自己想要的方式游玩。</p><p>随着你练习这些技能，你的经验值会增加，新的技能也会向你开放。</p><p>这里的关键点是：</p><p><em>在你练熟已经可用的技能之前，你无法获得其他技能。</em></p><p>你之所以没有察觉到那些有利可图的机会，是因为你没有能识别、选择并采取行动的技能。</p><p>当你朝着目标前进时，你需要学习并练习相应的技能，才能达到那些目标。</p><p>如果你把目标定得太高，你会不堪重负，也不知道该学什么。</p><p>你必须在自己当前的等级上游玩，获取升到下一级所必需的技能。</p><p>随着你等级的提升，你会往工具腰带里装满各种技能，让你能看清你所处的这个层面——它比你之前所在的那个较低层面更为广阔。</p><p>我第一次成功的尝试是自由职业网页设计。</p><p>这是一项任何人都能学会的单一技能。竞争激烈，大家为争取更高的价格而厮杀。</p><p>我知道，如果我想做点更赚钱的事，比如为服务型企业做营销转化漏斗，我就必须学习营销、文案写作、买家旅程等技能，才能做好这件事。</p><p>然后，当我进阶到“创作者”这个层级时，我需要把已知的东西结合起来，再加上像内容写作这样的新技能（我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时写作者》（2 Hour Writer）</a>中教授了你需要的所有技能）。</p><p>随着我等级的提高，我认识的人越来越多，我在多个领域中的自信也随之增长。</p><p>你能做的最糟糕的事，就是停止学习新技能，安于你当前所处的等级。</p><p>视角、感知和练习，是自信的三大基石。现在，让我们更深入一点。</p><h2 id="_2-理解你一开始为什么这么在乎" tabindex="-1">2）理解你一开始为什么这么在乎 <a class="header-anchor" href="#_2-理解你一开始为什么这么在乎" aria-label="Permalink to &quot;2）理解你一开始为什么这么在乎&quot;">​</a></h2><blockquote><p>如今，经过数十万年之后，我们仍然拥有为同一目的而设计的大脑。但由于我们已经越来越多地掌控了我们所处的环境，物理层面的压力已大大松弛，危险变得更加微妙——它们以人（而非豹子）的形式出现，以及他们那狡猾的心理，以及我们必须周旋于其中的那些精妙的政治与社会博弈。而正因为这些不那么明显的危险，我们最大的问题在于：我们的心智会逐渐对环境变得不那么敏感；我们转向内心，沉浸在自己的梦境和幻想之中。我们变得幼稚。——罗伯特·格林（Robert Greene）</p></blockquote><p>你太在乎，是因为这威胁到了你的自我形象。</p><p>你脑子里有一个关于“你是谁”的形象，当某个念头、想法或观点与之冲突时，你的情绪就开始爆发。你退缩了。你被困在生存模式里。你唯一能专注的，就是另一个人的看法。从那一刻起，因为你没能停下来打开思路，这种感觉就会被放大，主宰你的心智。</p><p>人类和动物之间有一个主要的区别。</p><p>动物试图在物理层面上生存。当它们的身体受到威胁时，它们会感到受威胁。它们试图复制自己基因中的信息。</p><p>由于自我反思意识的出现，人类试图在物理层面<em>和</em>心理层面同时生存。当我们的身体受到威胁时，我们会感到受威胁，但当我们的“心理身体”，也就是我们的自我形象受到威胁时，我们也同样会感到受威胁。我们试图复制我们基因中的信息，但也试图复制我们意识中的信息。</p><p>我们写书、交流、互相发短信、选择政治立场，这样我们所认同的那张思想之网，就能在我们死后继续存活下去。思想是精神上的精子。当你读一本书时，作者正在精神上让你受孕。你的自我形象，是你一生所接触过的一切思想的孩子。艺术家在他们的思想变得不朽时，获得了不朽——就像我们在柏拉图和亚里士多德的肉体消逝很久之后，仍然在引用他们一样。</p><p>这听起来可能有点怪，事实也确实如此，但我会留点时间让你自己去反思，判断它是否成立。如果这样理解有帮助的话，别把它想成是精神上的性行为，而是把它想成在你心中播种、浇水，让种子开出花朵。仔细想想，其实是一回事。如其在上，如其在下。</p><p>那么，我们为什么会在乎别人怎么想？</p><p>因为我们想要生存。</p><p>我们天生渴望得到部落的接纳。如果得不到接纳,我们就会成为局外人。我们会失去赖以生存的资源。如果你不认同父母如此深度认同的意识形态——比如共和党、民主党、基督教、伊斯兰教——他们会把你赶出家门,如果他们认同得足够深,甚至会因为你最喜欢的球队跟他们不一样而厌恶你(这是个极端的例子,但确实可能发生)。你的信念与父母的信念开战,他们会不惜一切代价求生存。这种心理感受不亚于在战斗中被刺伤。如果他们心智不够成熟,就会反过来刺伤你——把你赶出家门,你<em>会</em>感受到那种痛。</p><p>在某些情况下,在乎别人怎么想是很有道理的。在年轻、还没有能力独立生存和发展的时候,不想被赶出家门(或被反刺一刀),这是明智且具有策略性的。</p><p>但在现代生活的95%的情况下,当我们可以学习任何东西、做任何事情、achieve任何目标时,这种在乎完全是无用的。你并没有真正受到威胁。当有人在评论区嘲笑你的发际线时,你的生存并没有真正受到威胁。但你还没有学会驾驭和掌控自己的心智,所以你以为威胁是真实的,并成为了它的奴隶。你缺乏知识、技能和自我发展,无法自信地做任何你想做的事。</p><h2 id="_3-编程你的心智-让它停止在乎" tabindex="-1">3) 编程你的心智,让它停止在乎 <a class="header-anchor" href="#_3-编程你的心智-让它停止在乎" aria-label="Permalink to &quot;3) 编程你的心智,让它停止在乎&quot;">​</a></h2><p>你在乎别人怎么想,是因为你的心智被编程成了这样。</p><p>这对你来说已经是第二本能。</p><p>你从小就被编程去遵从命令。你的心智为了生存而自我编程。你把对生存的威胁——比如小时候触碰蜡烛火焰——记录为一件坏事。这说得通。你不想被责骂或烫伤。那是负面反馈,你的心智就是这样去解读它的。</p><p>你的父母大概没有教你如何掌控自己的心智,因为他们自己也没能掌控自己的。</p><p>下面是你开始重新编程心智的方法。</p><p>首先,你需要打破这个无意识的习惯。</p><p>你需要阻止这个程序继续执行。</p><p>任何时候你感觉到情绪反应,就<em>停下来。</em></p><p><em>停顿是改变心意的机会。</em></p><p>第二,练习元认知。质疑你的想法,让你的心智从狭隘的状态中打开。</p><p>问自己:“我真的在乎这件事吗?”</p><p>从那里开始,让一个想法触发另一个想法,直到紧张感释放。</p><p>当你做得足够多时,这就会变成一种习惯,你的心智也会随之转变。你会意识到你其实并不真的在乎;你的心智只是喜欢让你分心,阻止你获得满足与平静。</p><p>在情绪激烈的当下,这可能做不到,但在事后反思时,或者当你独自一人、在手机上看到某些内容后感到受威胁时,是可以做到的。</p><p>通过自我反思,你随时都可以重新编程你的心智。</p><h2 id="_4-社会给的路径-失败率100" tabindex="-1">4) 社会给的路径,失败率100% <a class="header-anchor" href="#_4-社会给的路径-失败率100" aria-label="Permalink to &quot;4) 社会给的路径,失败率100%&quot;">​</a></h2><blockquote><p>检验智慧的唯一真正标准,是你能否从生活中得到你想要的东西。——纳瓦尔·拉维坎特(Naval Ravikant)</p></blockquote><p>你在乎别人怎么想,是因为你对自己独立生存的能力没有信心。你依赖于别人给你一个角色,而不是自己去创造一个角色。</p><p>我要说几件可能会冒犯到你的事情。</p><p>换句话说,你可能会在乎我怎么想,所以现在正是练习上面所说内容的时候。</p><p><strong>1) 现代生活中默认的路径必然是一种失败,因为你根本没有一开始就设定好目的地。</strong></p><p>上学,找工作,买房子,让40年就那样过去,退休(也许)。</p><p>你实现的是别人想要的东西,而不是你自己想要的。那不是智慧,那是盲目的愚蠢。你没能质疑自己被灌输的程序。</p><p>那不是成功,那是彻头彻尾的失败。即使你身边的每个人都把你的物质财富看作成功,他们也没意识到,你并不是一个独特的人。你的个性和自我形象,与社会大众的克隆没什么区别。</p><p>在我的定义里,成功是创造你是谁。生活中的质量、乐趣和满足感,只是这个过程的副产品。</p><p><strong>2) 学校教育体系是一种构造,目的是让人保持愚昧,即便这并非其初衷。</strong></p><p>学校被创立出来,是为了把人教育成他们所在王国或社会中特定的角色。</p><p>这里的关键词是“特定角色”。</p><p>在他们受教育的整段时间里,他们追求的是一个目标。那个被分配给他们的目标,是为了让他们达到某种地位,让别人<em>觉得</em>他们很重要。这样他们就能生存下去,并从他人那里获取资源。这一个目标框定了他们有可能获取的所有知识(目标就是这样起作用的,它会框定你的心智去学习为了达成这个目标所需的新信息)。他们只研究一个领域,比如历史、金融、生物学。他们研究的是部分,不是整体。他们研究的是材料,不是关系。他们研究的是点,而不是连接的网络。</p><p>结果就是,他们在某一个领域拥有大量知识,这让他们对别人有用,而不是对自己有用。他们唯一的选择就是成为需要他们专业知识的人的奴隶。不是身体上的奴役,而是精神上的。他们不具备那种通才式的理解力,无法为自己设定的目标创造出自己的路径。</p><p>这跟在乎别人怎么想有什么关系?</p><p>因为仅仅为了达成别人分配给你的目标而学习,是极具破坏性的。它会把你锁死在一条单一路径上,只为了地位。它会把你变成一个目光狭隘的克隆人,看不到生活的深度,因为如果你真的看到了生活的深度,你就会停止在乎。</p><h2 id="_5-拥抱自然的指南针" tabindex="-1">5) 拥抱自然的指南针 <a class="header-anchor" href="#_5-拥抱自然的指南针" aria-label="Permalink to &quot;5) 拥抱自然的指南针&quot;">​</a></h2><p>你知道心智是如何运作的吗?</p><p>心智是一个系统,它帮助你实现已知的目标,并发现未知的目标。</p><p>你的心智一直在运转、谋划,并根据占据你心智的目标来理解现实。</p><p>这些目标,大多数时候,是你从所处文化中接受的<em>价值观</em>、父母和老师灌输给你的<em>信息</em>、生物性的生存需求等等的产物。你的目标往往是你所处环境的产物。</p><p>为什么这很重要?</p><p>因为理解这一点会决定你生命的结果。</p><p>占据你心智的目标,决定了你感知和学到的东西。</p><p>你的心智会自动接受或拒绝信息,以帮助你实现正在追求的目标。举个例子,如果你的目标仅仅是上学、找工作,你就只会注意到有助于实现这一目标的生活层面。但如果你的目标是活出最好的人生——一个稍微更全面、几乎无穷无尽的目标(一场无限的游戏)——你会注意到多得多的东西。可供你发现和获取的目标与技能将是无穷无尽的。只要你保持这个目标,生活就会保持其活力——因为它很容易被社会取代。</p><p>要点是:</p><p>你在乎别人怎么想,是因为你没有活在自己的小世界里。你没有被自己的愿景、使命,以及构成它们的目标所吸引到分心变得不可能的程度。</p><p>心流状态代表着最优体验。你的注意力沉浸在当下的目标中,你忘记了自己的忧虑。</p><p>要持续保持某种程度的心流,只有当你掌控了塑造你每一个行动——从早上起床到走在街上——的目标时,才能做到。</p><p>如果你想重新掌控自己的人生,你必须从零开始。</p><p>既然目标决定了你如何感知世界,进而决定了你所能获得的机会,那么社会给你设定的默认路径——以及它在你脑中残留的任何一丝痕迹——都对你的生活质量有害。</p><p>质疑你所知道的一切。反抗社会,亲自去弄清楚什么才是真实的。密切关注你的每一个想法和行动。问自己:“是我自己设定的目标,导致了这个结果吗?”</p><p>现在的问题是,你要如何带着确定性去驾驭人生?</p><p>你做不到。而且一开始你也并不处在一个安全或确定的位置上。</p><p>就我而言,今天是你的生日。你不再是那个被分配给你的身份。你重生了,因为你选择了重生,现在你可以开始重新编程的过程了。所以,生日快乐。</p><p>忘掉你对确定性和安全感的持续渴求吧。那只会把你困在另一个狭隘的领域里。</p><p>相反,拥抱自然的指南针。</p><ul><li>为你的未来创造一个愿景。让它变得宏大,甚至有点近乎痴狂。</li><li>把它逆向拆解成10年、1年、每月、每周的目标。</li><li>再把这些进一步拆解成你每天需要完成的优先任务。</li><li>这些优先任务将涉及自我教育和解决问题。</li></ul><p>你已经有效地为自己的心智创造了一个新的框架,让你能充分利用生活。</p><p>你正在给自己创造随时进入心流的机会。你有一串无穷无尽、充满挑战的目标,而你必须获得与之匹配的技能。</p><p><img src="'+a+'" alt=""></p><p>注意,这不是一个静态、狭隘的框架。它会随着你一起进化。要坦然接受重新审视你的计划并做出改变。</p><p>在那之后,你所做的一切都归结为识别和解决问题。问题是你在黑暗房间中的那道光。</p><ul><li>从你现在生活中那些具体、实际的问题开始。</li><li>解决你的健康问题。解决你的财务问题。解决你的人际关系问题。解决你的心理健康问题。</li><li>别被那些不在你直接经验范围内的问题分散注意力。</li></ul><p>当你解决问题时,新的问题会不断浮现出来。你可以去健身房解决自信问题,但那会揭示出一个更深层的问题。自信不是靠外在的样子解决的。它是一个内在的问题。所以去解决那个。从浅处开始,因为那是深入挖掘的唯一方法。</p><p><img src="'+i+'" alt=""></p><p>你要如何解决问题?</p><p>通过自我实验。不要把别人的解决方案、意识形态或建议当作定律来接受。你要用别人的技巧和方法进行实验,找到它们之间的交集,从而彻底解决问题。</p><p>很快你就会意识到,所有的问题最终都通向自我实现和自我发展。你深入得越深,就能越成功,并在这一过程中获得越多的技能。</p><h2 id="_6-热情的过程" tabindex="-1">6) 热情的过程 <a class="header-anchor" href="#_6-热情的过程" aria-label="Permalink to &quot;6) 热情的过程&quot;">​</a></h2><p>不幸的是,“热情”这个词已经沦为其原本含义的一个庸俗化版本。</p><p>互联网上充斥着各种标题和营销角度,大声宣称热情毫无用处,你不需要去寻找它,或者你应该去做别的事情。</p><p>热情是一个伟大、富有描述力、值得拥有的词。</p><p>你可以在骨子里感受到热情。</p><p>而如果你不过一种充满热情的生活,唯一的另一个选择又是什么呢?</p><p>当你对某件事充满热情时,你根本不在乎别人怎么想。</p><p>你会自己主动去研究它。它会成为你的逃离之所。</p><p>你会在社交层面拥有朋友,但在智识层面上,你的孤独也会让你完全心满意足。</p><p>与此同时,当你找到那些与你有共同热情的少数人时,一种牢不可破的联结便会形成。没有比这更好的感觉了。</p><p>你要如何发现自己的热情？</p><p>你需要知道几件事:</p><ul><li>热情是当进步变成执念的时候。</li><li>热情是尝试一切、然后发现那件你无法让自己离开的事情的过程。</li><li>热情不是在你现在所处的地方找到的。它是在你前进的路上被发现的。</li></ul><p>这些就是你的指南。</p><p>当你朝着自己的愿景解决问题、通过自我教育尝试你发现的潜在技巧和解决方案时,要时刻留意热情的迹象。</p><p>学习新知识会变成一种爱好,而不是一件苦差事。</p><p>打造一份事业会像孩子玩乐高一样有趣。</p><p>如果你想不再在乎别人怎么想,就去发现你的热情。</p><h2 id="_7-多写作" tabindex="-1">7) 多写作 <a class="header-anchor" href="#_7-多写作" aria-label="Permalink to &quot;7) 多写作&quot;">​</a></h2><p>你的大脑是现实的操作系统。</p><p>当你学会如何思考,你就学会了如何有效地驾驭各种情境,为自己和他人获得最有利的结果。换句话说,当你学会如何思考,你就能从生活中得到你想要的东西。</p><p>你要如何提升思考能力？把你的想法和点子当作乐高积木来对待。你不是一个聪明的思考者,是因为构成你思维的那些想法和点子是一团乱麻。你无法把它们看作独立的个体,也无法重新组织它们。</p><p>这就是写作发挥作用的地方。</p><p>写作是加速你思维锻造的工具。</p><p>用写作把自己写进一个能通向更好生活的世界观里。</p><p>当我按照我想要成为的那个人去写作时,我感觉最棒。</p><p>我从未把自己当作一个作家(大多数情况下现在依然如此),直到我意识到我学会的每一项其他技能都需要我去写作。</p><p>视频大纲、落地页、短信、邮件、广告、社交媒体内容,等等。即使我学的是另一项技能,比如平面设计或编程,我仍然得用写作,利用那些其他技能为那件事获取客户或顾客。</p><p>每个人都是作家。一旦你把这一点内化,并开始磨炼与让你的创意作品成功相关的这项技能,你就会开始看到你甚至不知道自己一直在追求的好处。</p><ul><li>写作迫使你组织和表达你的想法。你会成为一个更好的决策者。你会慢慢开始驾驭脑中的混乱。</li><li>写作是完美的反馈机制。如果你的读者没有成长,或者你没有从你的作品中获得报酬,那就说明你需要提升用写作说服他人的能力。</li><li>你写得越好,你想得就越清楚,而如果你的想法影响着你大部分的习惯、行动、优先事项以及理解复杂情境的能力——写作会极大地增加你成功的机会。</li></ul><p>你不需要英语学位才能写作。你给朋友发短信时,已经比大多数学校作文更有影响力了。如果你能用一条短信说服朋友和你一起吃晚饭,那么在真正重要的现实应用中,你就比大多数学者更擅长写作。</p><p>多亏了社交媒体和互联网,而且只要你有能力去学习它们的运作方式,一条简单的、如短信般的社交媒体帖子就能触达数十万人,其中许多人愿意为你所提供的价值付费。</p><p>你能养成的最有影响力的习惯,就是每天早晨第一件事,进行30到60分钟的写作练习。要有意识地去做。让你自己和你的作品取得成功,取决于你能否让你的写作——无论是免费还是付费的——出现在那些能与之共鸣的人面前。</p><p>我们将在未来的一封信中讨论我是如何在 Kortex 内部做到这一点的。</p><p>目前,<a href="https://kortex.co/" target="_blank" rel="noreferrer">加入等候名单</a>,我们将在9月20日开始逐步向大家开放这个应用的使用权限。</p><h2 id="_8-宇宙式思维-kosmic-thinking" tabindex="-1">8) 宇宙式思维（Kosmic Thinking） <a class="header-anchor" href="#_8-宇宙式思维-kosmic-thinking" aria-label="Permalink to &quot;8) 宇宙式思维（Kosmic Thinking）&quot;">​</a></h2><p>如果你想不再在乎别人怎么想,学会把视角拉远。</p><p>当我说拉远,我是指一直拉到极致。能拉多远就拉多远。超越可观测的宇宙(cosmos),走向那个更本源的“宇宙”(Kosmos)。</p><p>对古希腊哲学家来说,世界是一个“kosmos”,用来描述宇宙是一个有序而和谐的系统。这与今天那种还原论式的科学范式恰恰相反——后者把宇宙看作一台机器(试图通过研究宇宙的各个部分来理解现实,而不是研究各部分之间构成整体的关系)。</p><p>在这个意义上,“Kosmos(宇宙)”几乎等同于所有对终极实在的诠释:上帝、梵(Brahman)、无限者、源头(Source)、特欧特尔(Teotl),以及宗教领袖和神秘主义大师们所暗示的其他一切。</p><p>对希腊人来说,当以部分与整体来思考时,每一个部分都在为宇宙的和谐服务,各自承担着某种目的。</p><p>其他哲学家,比如阿伦·瓦茨(Alan Watts),把世界描述为一个有机体——一个由各种关系联结在一起、正常运作的生态系统。</p><p>亚里士多德认为,一件事物的终极因就是它的功能,而对任何事物的完整解释都必须考虑它的终极因。这引出了目的论和控制论这两个领域。</p><p>目的论(telos意为“目标”,logos意为“道理/理由”)是指通过指出某事物的目的、终点或目标来解释它的理念。</p><p>控制论研究的是系统如何自我调节、自我组织,以趋向该系统的最终目标。</p><p>当把这两者结合并应用到心智上时,我们便能开始理解自己的行动和行为,并通过这种理解去改变它们。</p><p>心智是一个接受和拒绝信息、以帮助实现其目标的系统。我之前讨论过这一点,但现在你必须明白,你的行为是可以用你的目的来解释的。</p><p>人类是以目标为导向的生物。你总是有一个目标。但当那个目标是被别人强加给你的,而你对此毫无自觉时,你就会在意别人怎么想,而这会慢慢摧毁你的生活。</p><p>通过与你最高自我的目的、以及宇宙(Kosmos)本身的目的相协调——正如我在书中所讨论的那样——生活会变得更有意义,你也能开始优雅地驾驭它。</p><p>我们可以深入探讨现实的本质,但在我看来,最好的方式是通过观察你自己的心智,并留意那些反映在你周围世界中的模式。</p><p>说到对某个情境“不在乎”,你之所以在乎别人怎么想,是因为你看不到全局。你看不到你所处的那个生态系统。你不理解自己的目的,也不理解处于那个情境中其他人的目的,以及这两种目标为何没有对齐——所以,当然会产生心理上的冲突。</p><p>你无法采纳对方的视角去理解他们是如何与这个情境互动的。你也无法拓宽自己的视角以找到出路。你看不清那个情境中每个变量的因果关系,而正是这些因果关系,能让你获得清晰的认知,并有信心地向前推进。</p><p>你会因为某人的政治言论而感到被冒犯,是因为你不理解他们的世界观,以及是什么导致他们说出那句话。你无法拉远视角,看清你的被冒犯感对对方的观点几乎不会产生任何影响,而且反而可能让对方的反应变得更糟,最终导致一场浪费时间的争吵。</p><p>我所说的“宇宙式思维”,是指系统思维,再加一点魔力和灵性色彩。我很喜欢这个主题,但一直没写够,所以我们会把这方面的大部分内容留给未来的一封信来讲。</p><p>宇宙式思维讲的是放手,拓展你的心智,以一种更高、不受任何单一范式局限的视角去观察情境,理解整体与其各部分(包括你自己)的目的,并引导自己走向一个能让你的心智变得清晰、让你朝那个更高目的持续前进的决定。</p><p>所以,再说一次,当你感觉自己开始变得紧张和易怒时,先停下来。</p><p>把视角拉远。如实地看待这个情境。如果你无法控制它,就放手。去找到那些能通向秩序的联系。</p><hr><p><a href="/en/letters/8-steps-to-just-stop-giving-a-fck">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',237))])}const T=l(d,[["render",m]]);export{x as __pageData,T as default};
